import {CHARACTERS} from './content.js';
export const DEFAULT_SETUP={opponents:[],seatLevels:[],startingCash:3200,startingTickets:60,mapVersion:2,randomStart:true,seed:''};
export function setupError(config,character,count){const chosen=(config.opponents||[]).slice(0,count-1).filter(id=>id&&id!=='random');if(chosen.includes(character))return '电脑角色不能与你选择的角色相同。';if(new Set(chosen).size!==chosen.length)return '每名角色只能占一个席位，请将重复角色改为随机。';if(chosen.some(id=>!CHARACTERS.some(c=>c.id===id)))return '存在未制作的角色。';if(config.seed!==undefined&&config.seed!==''&&(!/^\d+$/.test(String(config.seed))||+config.seed<1||+config.seed>4294967295))return '对局种子请输入 1—4294967295，留空则随机。';return '';}
export function rosterFor(character,count,opponents,seed){if(!opponents)return[character,...CHARACTERS.filter(c=>c.id!==character).map(c=>c.id)].slice(0,count);const seats=Array.from({length:count-1},(_,i)=>opponents[i]||'random'),error=setupError({opponents:seats,seed:''},character,count);if(error)throw new RangeError(error);const fixed=new Set([character,...seats.filter(id=>id!=='random')]),pool=CHARACTERS.map(c=>c.id).filter(id=>!fixed.has(id));let state=(seed>>>0)^0xa53c9e27;const random=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};for(let i=pool.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}return[character,...seats.map(id=>id==='random'?pool.pop():id)];}
export function normalizeSetup(raw={}){return{opponents:Array.isArray(raw.opponents)?raw.opponents.slice(0,5).map(id=>id==='dounai'?'naicha':id):[],seatLevels:Array.isArray(raw.seatLevels)?raw.seatLevels.slice(0,5):[],startingCash:[2000,3200,5000,8000].includes(+raw.startingCash)?+raw.startingCash:3200,startingTickets:[0,60,120].includes(+raw.startingTickets)?+raw.startingTickets:60,mapVersion:+raw.mapVersion===1?1:2,randomStart:raw.randomStart!==false,seed:String(raw.seed||'')};}
